package com.bank.flink.dt;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// APPEND mode: every arriving row is a new row; nothing is ever updated.
class AppendDynamicTable {
    private static final Logger log = Logger.getLogger(AppendDynamicTable.class.getName());

    private final List<Txn> rows = new ArrayList<>();

    void onRow(Txn txn) {
        rows.add(txn); // only ever grows
        log.info(() -> "APPEND +INSERT account=" + txn.getAccountId()
                + " amount " + txn.getAmount() + " (table size " + rows.size() + ")");
    }

    int size() { return rows.size(); }
}
