package com.bank.flink.dt;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.Logger;

// UPSERT mode: keyed by account; a known account's row is UPDATED in place,
// emitting a changelog (retract old + insert new).
class UpsertDynamicTable {
    private static final Logger log = Logger.getLogger(UpsertDynamicTable.class.getName());

    private final Map<String, BigDecimal> balanceByAccount = new LinkedHashMap<>();

    void onRow(Txn txn) {
        String acct = txn.getAccountId();
        boolean existed = balanceByAccount.containsKey(acct);
        BigDecimal oldBal = balanceByAccount.getOrDefault(acct, BigDecimal.ZERO);
        BigDecimal newBal = oldBal.add(txn.getAmount());
        balanceByAccount.put(acct, newBal);

        if (existed) {
            log.info(() -> "UPSERT -RETRACT account=" + acct + " old=" + oldBal);
            log.info(() -> "UPSERT +INSERT  account=" + acct + " new=" + newBal);
        } else {
            log.info(() -> "UPSERT +INSERT  account=" + acct + " new=" + newBal + " (new key)");
        }
    }

    Map<String, BigDecimal> snapshot() { return balanceByAccount; }
}
