package com.bank.flink.dt;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

// STATIC batch table: a fixed snapshot queried ONCE; the answer never changes.
class StaticBatchTable {
    private static final Logger log = Logger.getLogger(StaticBatchTable.class.getName());

    private final List<Txn> snapshot;

    StaticBatchTable(List<Txn> snapshot) {
        this.snapshot = List.copyOf(snapshot); // frozen at load time
    }

    // Query once: total across the frozen snapshot. Terminates with a final result.
    BigDecimal totalOnce() {
        BigDecimal total = snapshot.stream().map(Txn::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
        log.info(() -> "STATIC batch query returns FINAL total=" + total + " (never changes)");
        return total;
    }
}
