package com.bank.flink.dt;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: same transactions into append vs upsert dynamic tables,
// contrasted with a static batch query.
public class DynamicTableDemo {
    private static final Logger log = Logger.getLogger(DynamicTableDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new DtLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        List<Txn> stream = List.of(
            new Txn("SAV2001", new BigDecimal("1000")),
            new Txn("CUR3001", new BigDecimal("500")),
            new Txn("SAV2001", new BigDecimal("250"))
        );

        log.info(() -> "--- APPEND dynamic table (grows) ---");
        AppendDynamicTable append = new AppendDynamicTable();
        for (Txn t : stream) append.onRow(t);

        log.info(() -> "--- UPSERT dynamic table (updates in place) ---");
        UpsertDynamicTable upsert = new UpsertDynamicTable();
        for (Txn t : stream) upsert.onRow(t);
        log.info(() -> "UPSERT final balances = " + upsert.snapshot());

        log.info(() -> "--- STATIC batch table (one fixed answer) ---");
        StaticBatchTable staticTable = new StaticBatchTable(stream);
        staticTable.totalOnce();
    }
}

// ─── Would be in DtLogFormatter.java in a real project ───
class DtLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                record.getMessage());
    }
}
